	input := `{"timestamp":"2026-01-02T00:00:00Z","action":"登录","user":"用户😀","paired":"😀",` +
		`"escaped_pair":"` + escGrinning + `","replacement":"�","escaped_replacement":"` + escReplacement + `"}`
